772	    /// Lint a single file, returning an empty diagnostics list if the file is ignored.
773	    fn run_file(&self, uri: &Uri, content: Option<&str>) -> Result<Vec<Diagnostic>, String> {
774	        let Some(uri_path) = uri.to_file_path() else {
775	            return Ok(Vec::new());
776	        };
777	        if self.is_ignored(&uri_path) {
778	            return Ok(Vec::new());
779	        }
780	
781	        let reports = self.lint_path(&uri_path, uri, content)?;
782	
783	        let mut diagnostics = Vec::with_capacity(reports.len());
784	        // mostly all diagnostics will have code actions (fix + ignoring line/file), only following diagnostics won't:
785	        // - inverted diagnostics (related spans for the diagnostics)
786	        // - diagnostics with span(0,0) and no fixes
787	        // - tsgolint internal diagnostics
788	        // - unused directives diagnostics
789	        let mut code_actions = vec![];
790	        for report in reports {
791	            diagnostics.push(report.diagnostic);
792	
793	            if let Some(code_action) = report.code_action {
794	                code_actions.push(code_action);
795	            }
796	        }
797	
798	        self.code_actions.pin().insert(uri.clone(), Some(code_actions));
799	
800	        Ok(diagnostics)
801	    }
